import sys
sys.exit(0)

MOD = 10**9 + 7

def count_stepping_numbers(low: str, high: str) -> int:
    def count_up_to(s):
        n = len(s)
        from functools import lru_cache
        @lru_cache(maxsize=None)
        def dp(pos, last, tight, started):
            if pos == n:
                return 1 if started else 0
            limit = int(s[pos]) if tight else 9
            total = 0
            for d in range(0, limit + 1):
                if not started and d == 0:
                    total += dp(pos+1, -1, False, False)
                elif not started:
                    total += dp(pos+1, d, tight and d == limit, True)
                elif abs(d - last) == 1:
                    total += dp(pos+1, d, tight and d == limit, True)
            return total % MOD
        return dp(0, -1, True, False)
    return (count_up_to(high) - count_up_to(str(int(low)-1))) % MOD
